/* M08 — group handoff, content provenance, and permissions request. */
(() => {
  const {$,esc,load,save,download}=LB;
  const tasks=[
    {id:'01',title:'Lobby & round flow',file:'01-lobby.js',location:'Lobby + status bar above the table',scope:'Player setup, private handovers, legal turns, and round flow. Shared rules live in game-engine.js.',done:['Two to six players receive five cards each and take private turns.','Next-stage labels and navigation work by keyboard.'],contract:'Reads LB.game; uses start/reveal/hide/draw; listens for game:changed.',pair:'Pair with M07 for the full player journey.'},
    {id:'02',title:'News & context cards',file:'02-news.js',location:'Main table, top left',scope:'News card, source/date details, context card, and content data.',done:['Every card has a text version and provenance.','New cards expose title and sentences for the reading module.'],contract:'Reads LB.game.story/contexts and cards.js; emits reading:* events.',pair:'Pair with M03 for the card experience.'},
    {id:'03',title:'Evidence hand',file:'03-evidence.js',location:'Directly beneath the news card',scope:'Private evidence/action hands, same-side selection, and sample action effects.',done:['Selecting a card updates its pressed state and excerpt.','Selection works without dragging or relying on color.'],contract:'Reads LB.game.player.hand/draft; emits draft:changed; uses engine.action.',pair:'Pair with M02; coordinate selected IDs with M05.'},
    {id:'04',title:'Reading & listening',file:'04-reading.js',location:'Right panel; above the cards on mobile',scope:'Text size, font, spacing, contrast, read-aloud and synchronized highlighting.',done:['Read, pause, resume, and stop work on supported voices.','Unsupported speech has a readable fallback; zoom and keyboard work.'],contract:'Listens for reading:*; owns lb-demo-reading preferences only.',pair:'Pair with M05 for accessibility. Never count tools as guide use.'},
    {id:'05',title:'Response & dictation',file:'05-response.js',location:'Below the evidence hand',scope:'Position choice, editable reasoning, microphone consent, and submission.',done:['A drop requires one side and confirmation; explanation is optional and empty cases are clearly confirmed.','Voice input is opt-in and never auto-submits; typing always works.'],contract:'Writes player.draft; engine.submit forces the all-player drop.',pair:'Pair with M04; coordinate the submission shape with M07.'},
    {id:'06',title:'Optional AI guide',file:'06-guide.js',location:'Right panel, below reading settings',scope:'Optional guide, rule help, thinking prompts, and transparent assistance history.',done:['The guide is off until enabled; scripted output is labeled.','Prompts support reasoning and do not choose or grade the answer.'],contract:'Owns player.guideEnabled/guideUses; neither affects score.',pair:'Pair with M08 for permitted content and AI boundaries.'},
    {id:'07',title:'Reflection & review',file:'07-reflection.js',location:'Dedicated screen after submission',scope:'Case reveal, group evidence review, evidence totals, ties, round wins, match end, reflection and export.',done:['Shows the submitted evidence and guide history accurately.','Round points award once, ties each gain one, next rounds reset hands, and matches finish.'],contract:'Reads LB.game.cases/history; engine.count/award/nextRound; session reflection.',pair:'Pair with M01; agree the argument data shape with M05.'},
    {id:'08',title:'Team & content stewardship',file:'08-team.js',location:'Team blueprint + Content & rights screens',scope:'Module ownership, acceptance criteria, source list, and rights request.',done:['Members can claim one or two modules and export the plan.','Every real card has recorded permission before import or AI use.'],contract:'Owns lb-demo-assignments; no content uploader or live AI integration.',pair:'Pair with M06; coordinate shared styles and final integration.'}
  ];
  const raw=load('assignments',{});const assignments=raw&&typeof raw==='object'?raw:{};
  const draft=`Subject: Permission request — LAMBOOZLED! digital course prototype and accessibility / AI use

Dear TC Press Permissions Team,

We are students at [institution] in [course], developing a noncommercial course prototype based on LAMBOOZLED! The Media Literacy Card Game by Ioana Literat, Yoo Kyung Chang, and the Media and Social Change Lab (ISBN 9780807764626).

May we digitize [list the exact cards, rule passages, and artwork] for [number of students/instructors], accessible through [password-protected course site] from [start date] to [end date]? Please confirm who controls digital adaptation rights and whether an existing digital version is available for this purpose.

We propose read-aloud with synchronized highlighting, adjustable reading settings, and optional speech-to-text responses. May we make the necessary text/audio adaptations, and what attribution, notices, storage, and deletion conditions should we follow?

We are also considering an optional AI guide for rule explanations, hints, and reflection. Please distinguish permission to (1) send approved excerpts in prompts, (2) store approved text or embeddings for retrieval, and (3) generate explanations or hints. We do not propose training or fine-tuning a model. Before using any service, we would identify the provider, exact content sent, retention, and training settings for your approval.

Does permission cover a recorded class presentation, portfolio screenshots, or a public demo? We will treat those as separate uses unless expressly covered. Please also confirm whether the name, logo, or card artwork may appear, and whether any third-party material needs separate clearance.

Our current sample uses original fictional cards and a scripted guide. Please let us know any fees, limitations, required wording, or additional permissions needed.

Thank you,
[Names, course, instructor, institution, contact details]`;
  LB.modules.team=function(){
    $('#team-module').innerHTML=`<div class="team-intro"><p>Four members, two modules each. The demo now supports pass-and-play turns, labeled sample actions, the shared drop, and scoring. Each pair below owns one part of the working game. Assignments are saved on this browser; download the plan to share it with your group.</p><div class="button-row"><button class="button" id="export-plan">Download team plan ↓</button><button class="button" id="print-plan">Print module checklists</button><a class="button primary" href="wireframe.html">Open four-person wireframe →</a><a class="button" href="wireframe.html" download="Lamboozled-Four-Person-Wireframe.html">Download wireframe ↓</a></div></div><div class="wire-map"><p class="eyebrow">DESKTOP PLACEMENT / CLICK A BLOCK TO FIND ITS TASK</p><h2>The table, broken into buildable parts.</h2><div class="wire-map-layout"><a class="wire-box wire-wide" href="#task-01"><b>M01</b> Lobby → round status → navigation</a><div class="wire-map-left"><a class="wire-box" href="#task-02"><b>M02</b> News card + context<small>Main reading area</small></a><a class="wire-box" href="#task-03"><b>M03</b> Evidence hand<small>Inspect · select · compare</small></a><a class="wire-box" href="#task-05"><b>M05</b> Your response<small>Position · type or dictate · submit</small></a></div><div class="wire-map-right"><a class="wire-box" href="#task-04"><b>M04</b> Reading tools<small>Read-aloud · size · spacing · contrast</small></a><a class="wire-box" href="#task-06"><b>M06</b> Optional AI guide<small>Rules · hints · assistance history</small></a></div><a class="wire-box wire-wide" href="#task-07"><b>M07</b> After submission → reflection & review</a><a class="wire-box wire-wide" href="#task-08"><b>M08</b> Project screens → team plan & content permissions</a></div><p class="support-note">Mobile: navigation → reading tools → optional guide → news → evidence → response. Reflection opens as a separate screen. Use “Wireframe view” to see these IDs on the working sample.</p></div><div class="pairings"><h2>A four-person build plan.</h2><p>Two modules each, with shared testing. These are starting responsibilities; rebalance after your first sprint. The <a href="wireframe.html#rules">rules checklist</a> distinguishes implemented mechanics from sample content and demo choices.</p><div class="handoff-pairs"><article><h3>A · Game flow & results</h3><p><strong>M01 + M07</strong> · Lobby, round flow, reflection.</p><p><strong>Own &amp; test:</strong> turn engine, everyone’s drop, evidence totals, ties, and round wins. Coordinate state with B.</p></article><article><h3>B · Cards & evidence</h3><p><strong>M02 + M03</strong> · News, context, evidence hand.</p><p><strong>Own &amp; test:</strong> 1 news + 4 context, deal 5 cards per player, deck/draw logic, applicability and labeled sample action effects.</p></article><article><h3>C · Access & responses</h3><p><strong>M04 + M05</strong> · Reading tools, typed and spoken explanations.</p><p><strong>Own &amp; test:</strong> case submission to the turn engine, accessible turn announcements, speech fallbacks and keyboard review.</p></article><article><h3>D · Guide & integration</h3><p><strong>M06 + M08</strong> · Optional guide, team and content records.</p><p><strong>Own &amp; test:</strong> shared-file integration, complete-round tests, deployment and source handoff. Keep live AI as an extension.</p></article></div><p><strong>Same handoff for everyone:</strong> two modules, acceptance checks, and a short integration note. A reviews B; B reviews A; C reviews D; D reviews C. All four help with device and accessibility testing.</p></div><div class="team-grid">${tasks.map(t=>`<article class="panel task-card" id="task-${t.id}"><div class="task-head"><span class="task-id">${t.id}</span><div><h3>${t.title}</h3><p>${t.location}</p></div></div><p>${t.scope}</p><code>dist/modules/${t.file}</code><strong style="font-size:11px">DONE WHEN</strong><ul>${t.done.map(d=>`<li>${d}</li>`).join('')}</ul><p><strong>Connects through:</strong> ${t.contract}</p><p>${t.pair}</p><div class="assignment-row"><label for="owner-${t.id}">MODULE OWNER<input type="text" id="owner-${t.id}" maxlength="60" data-owner="${t.id}" placeholder="Add a member’s name" value="${esc(assignments[t.id]?.owner||'')}"></label><label for="status-${t.id}">STATUS<select id="status-${t.id}" data-status="${t.id}"><option value="available">Available</option><option value="claimed">Claimed</option><option value="building">Building</option><option value="review">Ready for review</option></select></label></div></article>`).join('')}</div><p class="status-text" role="status" id="assignment-status">Assignments are local to this browser, not synchronized with teammates.</p><div class="notice" style="margin-top:24px"><strong>Integration owner: Member D.</strong> Coordinate and review edits to <code>core.js</code>, <code>app.js</code>, <code>index.html</code>, and <code>styles.css</code>, <code>playful.css</code>, and <code>game.css</code>. Each module has its own JavaScript file. Coordinate shared markup and styles before merging.</div>`;
    tasks.forEach(t=>{$('#status-'+t.id).value=['available','claimed','building','review'].includes(assignments[t.id]?.status)?assignments[t.id].status:'available';});
    document.querySelectorAll('[data-owner],[data-status]').forEach(el=>el.addEventListener('change',()=>{const id=el.dataset.owner||el.dataset.status;assignments[id]={owner:$('#owner-'+id).value.trim(),status:$('#status-'+id).value};$('#assignment-status').textContent=save('assignments',assignments)?'Plan saved on this browser. Download a copy for your group.':'Browser storage is unavailable. Download your plan before closing.';}));
    $('#export-plan').onclick=()=>{tasks.forEach(t=>assignments[t.id]={owner:$('#owner-'+t.id).value.trim(),status:$('#status-'+t.id).value});download('lamboozled-team-plan.md','# LAMBOOZLED! — Course team plan\n\nLocal snapshot; coordinate ownership with the group.\n\nFour-person plan: A = M01/M07 (flow, turns, drop, scores); B = M02/M03 (cards, decks, evidence, action effects); C = M04/M05 (reading, dictation, case input); D = M06/M08 (guide, content records, integration and testing).\n\nFull-game wireframe: https://lamboozled-course-studio.eku2101.chatgpt.site/wireframe.html\nThe current sample is a playable local pass-and-play game with original sample cards and labeled sample actions. Each member hands off two modules, acceptance checks, and a short note. All four help with integration and device testing.\n\n'+tasks.map(t=>`## M${t.id} — ${t.title}\n\nOwner: ${assignments[t.id]?.owner||'Unassigned'}\nStatus: ${assignments[t.id]?.status||'available'}\nFile: dist/modules/${t.file}\nPlacement: ${t.location}\n\n${t.scope}\n\n${t.done.map(d=>'- [ ] '+d).join('\n')}\n\nIntegration: ${t.contract}\n${t.pair}\n`).join('\n'),'text/markdown');};
    $('#print-plan').onclick=()=>window.print();
    document.querySelectorAll('.wire-box').forEach(link=>link.onclick=e=>{e.preventDefault();const target=$(link.getAttribute('href'));target.scrollIntoView({behavior:'auto',block:'start'});const input=target.querySelector('input');input.focus({preventScroll:true});});
    renderPermissions();
  };
  function renderPermissions(){
    $('#permissions-module').innerHTML=`<div class="notice"><strong>Permission is not yet established.</strong> This sample contains original fictional cards and original demo instructions. It is an independent course concept, not an authorized digital edition.</div><div class="permission-layout"><div><section class="panel panel-pad"><p class="eyebrow">CONTENT & RIGHTS / CHECKED 17 NOV 2026</p><h2>Build the prototype.<br>Clear the content separately.</h2><p>For a U.S. course project, an educational purpose is relevant to fair use, but it does not automatically authorize copying the complete deck. Ask your institution’s copyright adviser if you plan to rely on an exception.</p><ul><li>Game ideas and methods of play are different from protected rulebook wording, card text, and artwork.</li><li>The research article has a CC BY 4.0 license. That alone does not establish a license for the separately published complete game.</li><li>Teachers College Press directs non-coursepack reproduction requests to <a href="mailto:tcpressrights@tc.columbia.edu">tcpressrights@tc.columbia.edu</a>. Its page asks applicants to allow six to eight weeks.</li><li>Teachers College reported a digital redesign in 2023. Ask whether an existing digital version or a course license is available.</li></ul><p>This is general permission guidance, not a determination that your specific use is lawful.</p><div class="source-list"><a href="https://www.tcpress.com/pages/permissions" target="_blank" rel="noreferrer">Publisher: permissions and accessibility requests ↗</a><a href="https://digitalcommons.uri.edu/jmle/vol13/iss1/5/" target="_blank" rel="noreferrer">Creators’ research article and article license ↗</a><a href="https://www.tc.columbia.edu/articles/2023/may/social-justice-drives-discourse-at-masclabs-mediafest-2023/" target="_blank" rel="noreferrer">Teachers College: digital redesign, 2023 ↗</a><a href="https://www.copyright.gov/register/tx-games.html" target="_blank" rel="noreferrer">U.S. Copyright Office: games ↗</a><a href="https://www.copyright.gov/fair-use/more-info.html" target="_blank" rel="noreferrer">U.S. Copyright Office: educational use and fair use ↗</a></div></section><section class="panel panel-pad" style="margin-top:24px"><h2>Ask about AI explicitly.</h2><p>No game-specific AI permission was verified in the sources reviewed. Propose these boundaries for written approval:</p><ul><li>Identify exactly which text or images may be sent to which AI provider.</li><li>Distinguish prompts, retrieval/embeddings, generated adaptations, and model training. Do not assume permission for one includes the others.</li><li>Specify storage, retention, deletion, access, and provider training settings. Use institution-approved services.</li><li>Keep the guide optional; cite approved rules, avoid answer selection or automatic grading, and invite players to check its help.</li><li>Obtain separate clearance for public demos, portfolio images, branding, or third-party content when needed.</li></ul><p class="support-note">The sample guide sends nothing to an AI service. Browser speech features can use provider services; dictation requires a separate opt-in.</p></section></div><section class="panel panel-pad"><div class="panel-heading"><h2>A request you can adapt.</h2><span class="chip">DRAFT · NOT SENT</span></div><p class="support-note" style="margin:0 0 18px">Fill in the brackets and list the exact material. The draft asks for terms; it does not claim approval.</p><pre class="draft">${esc(draft)}</pre><button class="button primary" id="download-request" style="margin-top:22px">Download permission request ↓</button></section></div>`;
    $('#download-request').onclick=()=>download('lamboozled-permission-request.txt',draft);
  }
})();
